let PROF = PROF_HULL;
export function useFaceProfile(on = true) { PROF = on ? PROF_FACE : PROF_HULL; }
export const TAU = Math.PI * 2, D2R = Math.PI / 180;
export function headR(th, ph) {
  let t = (th + Math.PI) / TAU * NT; t = ((t % NT) + NT) % NT;
  const p = Math.min(Math.max(ph / Math.PI * NP, 0), NP - 1e-6);
  const t0 = Math.floor(t), p0 = Math.floor(p), ft = t - t0, fp = p - p0;
  const a = (ti, pi) => PROF[ti * (NP + 1) + pi];
  return (a(t0, p0) * (1 - ft) + a(t0 + 1, p0) * ft) * (1 - fp) + (a(t0, p0 + 1) * (1 - ft) + a(t0 + 1, p0 + 1) * ft) * fp;
}
export function dirOf(th, ph) { const s = Math.sin(ph); return [s * Math.sin(th), Math.cos(ph), s * Math.cos(th)]; }
// 1.8.9: calotta del cranio vero del motore (HEAD.cranium in faceAR.js). Su una testa vera, in cima e sopra la fronte,
// il cranio è più alto e più avanti del profilo qui sopra (la cima arriva a y ≈ 13,3, il profilo a 10,5): una cuffia
// corta fatta sul profilo resta "dentro la testa" e il motore non può accendere la calotta. useCranium(m) (per
// effetto, prima di costruire; useCranium(0) dopo) fa in modo che headPt non scenda mai sotto la calotta + m cm,
// con un raccordo morbido: dove i capelli sono già fuori non cambia niente.
export const CRANIUM = { c: [0, 5.6, -4.8], r: [7.7, 7.7, 8.7] };
let CRM = 0;
export function useCranium(m = 0) { CRM = m || 0; }
// distanza da HC alla superficie della calotta nella direzione unitaria d (HC sta dentro la calotta)
export function craniumR(d) {
  const C = CRANIUM.c, R = CRANIUM.r;
  const q = [(HC[0] - C[0]) / R[0], (HC[1] - C[1]) / R[1], (HC[2] - C[2]) / R[2]], u = [d[0] / R[0], d[1] / R[1], d[2] / R[2]];
  const a = u[0] * u[0] + u[1] * u[1] + u[2] * u[2], b = q[0] * u[0] + q[1] * u[1] + q[2] * u[2], c = q[0] * q[0] + q[1] * q[1] + q[2] * q[2] - 1;
  return (-b + Math.sqrt(b * b - a * c)) / a;
}
export function headPt(THREE, th, ph, off) {
  const d = dirOf(th, ph);
  let r = headR(th, ph) + (off || 0);
  if (CRM) { const rc = craniumR(d) + CRM, k = 0.5; r = (r + rc + Math.sqrt((r - rc) * (r - rc) + k * k)) / 2; }
  return new THREE.Vector3(HC[0] + d[0] * r, HC[1] + d[1] * r, HC[2] + d[2] * r);
}
// φ tale che il punto sulla superficie abbia altezza y (bisezione, y decresce con φ)
export function phiForY(th, y) {
  // y decresce con φ solo fino al punto più basso (sotto il mento risale verso il collo): cerchiamo in [0, φ_min]
  let lo = 0, hi = Math.PI, ymin = 1e9, hiY = 0;
  for (let i = 60; i <= 180; i++) { const m = i / 180 * Math.PI, yy = HC[1] + headR(th, m) * Math.cos(m); if (yy < ymin) { ymin = yy; hi = m; } }
  if (y <= ymin) return hi;
  for (let i = 0; i < 26; i++) { const m = (lo + hi) / 2; (HC[1] + headR(th, m) * Math.cos(m) > y) ? lo = m : hi = m; }
  return (lo + hi) / 2;
}
// interpolazione lineare su chiavi [[gradi, valore], ...] (gradi crescenti, usa |θ| → simmetrico)
export function keyLerp(keys, deg) {
  deg = Math.abs(deg);
  if (deg <= keys[0][0]) return keys[0][1];
  for (let i = 1; i < keys.length; i++) if (deg <= keys[i][0]) { const [a, va] = keys[i - 1], [b, vb] = keys[i]; const f = (deg - a) / (b - a); return va + (vb - va) * (f * f * (3 - 2 * f)); }
  return keys[keys.length - 1][1];
}
export function clamp(x, a, b) { return x < a ? a : x > b ? b : x; }
export function smooth(a, b, x) { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); }
// rumore 2D deterministico (value noise)
export function hash2(x, y) { const s = Math.sin(x * 127.1 + y * 311.7) * 43758.5453; return s - Math.floor(s); }
export function vnoise(x, y) {
  const xi = Math.floor(x), yi = Math.floor(y), fx = x - xi, fy = y - yi, ux = fx * fx * (3 - 2 * fx), uy = fy * fy * (3 - 2 * fy);
  return (hash2(xi, yi) * (1 - ux) + hash2(xi + 1, yi) * ux) * (1 - uy) + (hash2(xi, yi + 1) * (1 - ux) + hash2(xi + 1, yi + 1) * ux) * uy;
}
export function rng(seed) { let a = seed >>> 0; return () => { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
// colore → [r,g,b] lineare, con fattore di luminosità k
export function rgb(THREE, hex, k = 1) { const c = new THREE.Color(hex); return [c.r * k, c.g * k, c.b * k]; }

// Geometria "guscio" sulla testa: griglia (θ, φ) fra top(θ) e bot(θ) a distanza headR+off, più eventuale "drappo" che scende sotto il bordo.
// opt: thMin, thMax (rad, default giro completo), segT, segP, top(th)→φ, bot(th)→φ, off(th, v, ph)→cm,
//      rimTuck (cm di rientro del bordo verso la pelle), color(th, v, ph, drapeS)→[r,g,b],
